package cache

import (
	"sync"
	"time"
)

type entry struct {
	value     interface{}
	expiresAt time.Time
}

// Cache is a thread-safe key-value store with per-entry TTL.
type Cache struct {
	mu      sync.RWMutex
	store   map[string]entry
	stopCh  chan struct{}
}

// New creates a Cache. cleanupInterval specifies how often expired entries
// are purged in the background (0 = no background cleanup).
func New(cleanupInterval time.Duration) *Cache {
	c := &Cache{
		store:  make(map[string]entry),
		stopCh: make(chan struct{}),
	}
	if cleanupInterval > 0 {
		go c.cleanupLoop(cleanupInterval)
	}
	return c
}

