package cache_test

import (
	"testing"
	"time"

	"github.com/ai-verification/ttl-cache/cache"
)

func TestSetAndGet(t *testing.T) {
	c := cache.New(0)
	c.Set("k", "v", time.Minute)
	val, ok := c.Get("k")
	if !ok || val != "v" {
		t.Fatalf("expected (v, true), got (%v, %v)", val, ok)
	}
}

func TestGetMissing(t *testing.T) {
	c := cache.New(0)
	_, ok := c.Get("nope")
	if ok {
		t.Fatal("expected false for missing key")
	}
}

func TestExpiry(t *testing.T) {
	c := cache.New(0)
	c.Set("k", "v", 20*time.Millisecond)
	time.Sleep(30 * time.Millisecond)
	_, ok := c.Get("k")
	if ok {
		t.Fatal("expected key to be expired")
	}
}

func TestNotExpiredYet(t *testing.T) {
	c := cache.New(0)
	c.Set("k", "v", time.Minute)
	_, ok := c.Get("k")
	if !ok {
		t.Fatal("expected key to not be expired")
	}
}

func TestDelete(t *testing.T) {
	c := cache.New(0)
	c.Set("k", "v", time.Minute)
	c.Delete("k")
	_, ok := c.Get("k")
	if ok {
		t.Fatal("expected key to be deleted")
	}
}

func TestCleanupGoroutine(t *testing.T) {
	c := cache.New(15 * time.Millisecond)
	defer c.Stop()
	c.Set("x", 1, 10*time.Millisecond)
	time.Sleep(40 * time.Millisecond)
	// After cleanup, expired entry should be gone from internal store
	_, ok := c.Get("x")
	if ok {
		t.Fatal("expected cleanup to remove expired entry")
	}
}
